package main

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"

	"github.com/aitaskmanager/ai-task-manager/internal/monitor"
	"github.com/egoist/mygo"
)

// TaskManager is the desktop bridge. Every exported method becomes a typed
// TypeScript call generated by `mygo generate`.
type TaskManager struct {
	service      *monitor.Service
	settingsPath string

	configMu       sync.Mutex
	configVersion  uint64
	restoreStarted bool
	restoreDone    chan struct{}
	apiKey         string
	readSecret     func(string) ([]byte, error)
}

func NewTaskManager() *TaskManager {
	manager := &TaskManager{
		service:    monitor.NewService(),
		readSecret: mygo.Secrets.Get,
	}
	if dir, err := mygo.App.Path(mygo.PathUserData); err == nil {
		manager.settingsPath = filepath.Join(dir, "ai-provider.json")
	}
	return manager
}

// startAIRestore loads persisted settings in the background. A Keychain read may
// wait for a macOS authorization prompt after an app update, so it must never
// delay the first window or block the settings UI indefinitely.
func (t *TaskManager) startAIRestore() {
	t.configMu.Lock()
	if t.restoreStarted {
		t.configMu.Unlock()
		return
	}
	t.restoreStarted = true
	t.restoreDone = make(chan struct{})
	version := t.configVersion
	done := t.restoreDone
	t.configMu.Unlock()

	go func() {
		defer close(done)
		if err := t.restoreAIProvider(version); err != nil {
			log.Printf("AI settings restore failed: %v", err)
		}
	}()
}

// waitForAIRestore limits how long a one-off AI request waits for the Keychain.
// A locked or stalled credential prompt must degrade to local rules instead of
// freezing the desktop bridge.
func (t *TaskManager) waitForAIRestore(timeout time.Duration) bool {
	t.startAIRestore()
	t.configMu.Lock()
	done := t.restoreDone
	t.configMu.Unlock()
	if done == nil {
		return true
	}
	timer := time.NewTimer(timeout)
	defer timer.Stop()
	select {
	case <-done:
		return true
	case <-timer.C:
		return false
	}
}

func (t *TaskManager) restorePending() bool {
	t.configMu.Lock()
	started := t.restoreStarted
	done := t.restoreDone
	t.configMu.Unlock()
	if !started || done == nil {
		return false
	}
	select {
	case <-done:
		return false
	default:
		return true
	}
}

func (t *TaskManager) beginConfigMutation() {
	t.configMu.Lock()
	t.configVersion++
	t.configMu.Unlock()
}

func (t *TaskManager) configChangedSince(version uint64) bool {
	t.configMu.Lock()
	defer t.configMu.Unlock()
	return t.configVersion != version
}

func (t *TaskManager) cacheAPIKey(key string) {
	t.configMu.Lock()
	t.apiKey = strings.TrimSpace(key)
	t.configMu.Unlock()
}

func (t *TaskManager) cachedAPIKey() string {
	t.configMu.Lock()
	defer t.configMu.Unlock()
	return t.apiKey
}

const aiSecretKey = "ai-provider-api-key"

type persistedAIProvider struct {
	Provider    string `json:"provider"`
	BaseURL     string `json:"baseUrl"`
	Model       string `json:"model"`
	AllowRemote bool   `json:"allowRemote"`
}

func (t *TaskManager) restoreAIProvider(version uint64) error {
	if t.settingsPath == "" {
		return nil
	}
	data, err := os.ReadFile(t.settingsPath)
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	if err != nil {
		return fmt.Errorf("无法读取已保存的 AI 配置: %w", err)
	}
	var saved persistedAIProvider
	if err := json.Unmarshal(data, &saved); err != nil {
		return fmt.Errorf("已保存的 AI 配置格式无效: %w", err)
	}
	if t.configChangedSince(version) {
		return nil
	}
	baseInput := monitor.AIProviderInput{
		Provider:    saved.Provider,
		BaseURL:     saved.BaseURL,
		Model:       saved.Model,
		AllowRemote: saved.AllowRemote,
	}
	// Publish non-secret configuration first so the UI can explain that the
	// model is configured but still waiting for a credential.
	if err := t.service.SetAIProvider(baseInput, "app"); err != nil {
		return err
	}
	key, err := t.readSecret(aiSecretKey)
	if errors.Is(err, mygo.ErrSecretNotFound) {
		return nil
	}
	if err != nil {
		return fmt.Errorf("无法从系统凭据库读取 API Key: %w", err)
	}
	if t.configChangedSince(version) {
		return nil
	}
	t.cacheAPIKey(string(key))
	baseInput.APIKey = string(key)
	return t.service.SetAIProvider(baseInput, "app")
}

// GetAISettings returns the model configuration without ever returning the
// API key. The key is kept in the operating system credential store.
func (t *TaskManager) GetAISettings() monitor.AISettings {
	t.startAIRestore()
	restoring := t.restorePending()
	settings := t.service.AISettings()
	settings.Restoring = restoring
	return settings
}

// SaveAISettings persists non-secret provider fields in the user data folder
// and the API key in the system credential store.
func (t *TaskManager) SaveAISettings(input monitor.AIProviderInput) (monitor.AIStatus, error) {
	if t.settingsPath == "" {
		return monitor.AIStatus{}, errors.New("无法定位应用配置目录")
	}
	newKey := strings.TrimSpace(input.APIKey)
	if newKey == "" {
		if !t.waitForAIRestore(2 * time.Second) {
			return monitor.AIStatus{}, errors.New("系统凭据仍在恢复中，请稍后再保存，或直接输入新的 API Key")
		}
		newKey = t.cachedAPIKey()
	}
	t.beginConfigMutation()
	input.APIKey = newKey
	// Validate all provider fields before writing either the config file or the
	// system credential. Invalid input must not leave a partially saved setup.
	if err := t.service.ValidateAIProvider(input); err != nil {
		return monitor.AIStatus{}, err
	}
	saved := persistedAIProvider{
		Provider:    input.Provider,
		BaseURL:     input.BaseURL,
		Model:       input.Model,
		AllowRemote: input.AllowRemote,
	}
	data, err := json.MarshalIndent(saved, "", "  ")
	if err != nil {
		return monitor.AIStatus{}, err
	}
	tempPath := t.settingsPath + ".tmp"
	if err := os.WriteFile(tempPath, append(data, '\n'), 0o600); err != nil {
		return monitor.AIStatus{}, fmt.Errorf("无法保存 AI 配置: %w", err)
	}
	if newKey != "" {
		if err := mygo.Secrets.Set(aiSecretKey, []byte(newKey)); err != nil {
			_ = os.Remove(tempPath)
			return monitor.AIStatus{}, errors.New("无法将 API Key 保存到系统凭据库")
		}
	}
	if err := os.Rename(tempPath, t.settingsPath); err != nil {
		_ = os.Remove(tempPath)
		return monitor.AIStatus{}, fmt.Errorf("无法保存 AI 配置: %w", err)
	}
	if err := t.service.SetAIProvider(input, "app"); err != nil {
		return monitor.AIStatus{}, err
	}
	t.cacheAPIKey(newKey)
	return t.service.AIStatus(), nil
}

// TestAIConnection sends one tiny completion request. It does not send a task
// snapshot and never returns or logs the API key.
func (t *TaskManager) TestAIConnection(input monitor.AIProviderInput) (monitor.AITestResult, error) {
	if strings.TrimSpace(input.APIKey) == "" {
		if !t.waitForAIRestore(2 * time.Second) {
			return monitor.AITestResult{}, errors.New("系统凭据仍在恢复中，请稍后重试，或直接输入新的 API Key")
		}
		input.APIKey = t.cachedAPIKey()
	}
	return t.service.TestAIConnection(context.Background(), input)
}

// ClearAISettings removes the saved provider and credential, then returns to
// environment-based or local-rules mode.
func (t *TaskManager) ClearAISettings() (monitor.AIStatus, error) {
	t.beginConfigMutation()
	t.cacheAPIKey("")
	if t.settingsPath != "" {
		if err := os.Remove(t.settingsPath); err != nil && !errors.Is(err, os.ErrNotExist) {
			return monitor.AIStatus{}, errors.New("无法删除 AI 配置")
		}
	}
	if err := mygo.Secrets.Delete(aiSecretKey); err != nil {
		return monitor.AIStatus{}, errors.New("无法从系统凭据库删除 API Key")
	}
	t.service.ClearAIProvider()
	return t.service.AIStatus(), nil
}

// Bootstrap returns the first snapshot. Live collection failures are surfaced
// to the UI so it can offer the deterministic demo mode explicitly.
func (t *TaskManager) Bootstrap(demo bool) (monitor.Snapshot, error) {
	return t.service.Snapshot(demo)
}

// Refresh returns a fresh snapshot for the polling loop.
func (t *TaskManager) Refresh(demo bool) (monitor.Snapshot, error) {
	return t.service.Snapshot(demo)
}

// AIStatus reports whether explanations are local-only or use an explicitly
// configured OpenAI-compatible endpoint. It never returns credentials.
func (t *TaskManager) AIStatus() monitor.AIStatus {
	t.startAIRestore()
	restoring := t.restorePending()
	status := t.service.AIStatus()
	status.Restoring = restoring
	return status
}

// Explain answers a read-only diagnostic question. The result cannot create an
// action token or execute a process signal.
func (t *TaskManager) Explain(question string, workloadID string, demo bool) (monitor.AIAnswer, error) {
	restored := t.waitForAIRestore(2 * time.Second)
	answer, err := t.service.Explain(question, workloadID, demo)
	if err == nil && !restored && answer.Source == "local-rules" && t.restorePending() {
		answer.Note = "系统凭据仍在恢复中，本次先使用本地规则；恢复完成后再次提问即可使用模型"
	}
	return answer, err
}

// Preview validates a reclaim candidate and creates a short-lived action plan.
func (t *TaskManager) Preview(workloadID string, demo bool) (monitor.ActionPlan, error) {
	return t.service.Preview(workloadID, demo)
}

// Execute consumes a preview token exactly once.
func (t *TaskManager) Execute(token string) (monitor.ActionResult, error) {
	return t.service.Execute(token)
}

func main() {
	manager := NewTaskManager()
	mygo.Bind(manager)

	monitorContext, cancelMonitor := context.WithCancel(context.Background())
	defer cancelMonitor()

	var mainWindow *mygo.Window
	focus := &notificationFocus{}
	mygo.App.OnNotificationClick(focus.handle)
	mygo.App.OnWillQuit(func(*mygo.QuitEvent) { cancelMonitor() })

	mygo.App.WhenReady(func() {
		mainWindow = mygo.NewWindow(mygo.WindowOptions{
			Title:           "AI 任务管理器",
			Width:           1440,
			Height:          900,
			MinWidth:        1024,
			MinHeight:       720,
			BackgroundColor: "light-dark(#f4f6f8, #0a0d12)",
			StateKey:        "main",
			URL:             "/",
		})
		focus.bind(func() {
			mygo.App.Focus()
			mainWindow.Show()
			mainWindow.Focus()
		})
		go newThermalMonitor(manager.service).run(monitorContext)
	})
	if err := mygo.App.Run(); err != nil {
		log.Fatal(err)
	}
}
